36	// CLONE AT CAPTURE. dealRound emits the same object REFERENCE to every member,
37	// so recording the reference would make "both players got the same slots" a
38	// comparison of one object with itself — an assertion that cannot fail, which
39	// is worse than no assertion. Independent copies make the check real: mutate
40	// one player's captured payload and the comparison must go red.
41	const record = (sid, event, payload) => {
42	  emitted.push({ sid, event, payload: structuredClone(payload) });
43	};
