2	// Pre-generated questions from Supabase Storage (public CDN). Mirrors src/utils/questions.ts.
3	const { normalizeAnswer } = require("./answerMatch");
4	
5	const BASE = (process.env.QUESTIONS_PUBLIC_BASE || "").replace(/\/$/, "");
6	const SUPPORTED_SCHEMA = 1;
7	const MANIFEST_TTL_MS = 60_000;
8	
9	let manifest = null;      // { at, value }
10	let testFiles = null;     // url -> object (test seam)
11	const files = new Map();  // `${version}:${key}` -> object
12	
13	async function getJson(url) {
14	  if (testFiles) {
15	    if (!(url in testFiles)) throw new Error(`test file missing: ${url}`);
16	    return testFiles[url];
17	  }
18	  const r = await fetch(url);
19	  if (!r.ok) throw new Error(`${url} ${r.status}`);
20	  return r.json();
21	}
22	
23	async function getManifest() {
24	  if (manifest && Date.now() - manifest.at < MANIFEST_TTL_MS) return manifest.value;
25	  const m = await getJson(`${BASE}/questions/manifest.json`);
26	  if (m.schema !== SUPPORTED_SCHEMA) throw new Error(`questions schema ${m.schema} unsupported`);
27	  manifest = { at: Date.now(), value: m };
28	  for (const k of files.keys()) if (!k.startsWith(`${m.version}:`)) files.delete(k);
29	  return m;
30	}
31	
32	async function cached(version, key, url) {
33	  const k = `${version}:${key}`;
34	  if (files.has(k)) return files.get(k);
35	  const v = await getJson(url);
36	  files.set(k, v);
37	  return v;
38	}
39	
40	async function loadNames() {
41	  const m = await getManifest();
42	  return cached(m.version, "names", m.names);
43	}
44	
45	async function loadIndex(game) {
46	  const m = await getManifest();
47	  const entry = m.games[game];
48	  if (!entry) throw new Error(`no questions for ${game}`);
49	  return cached(m.version, `${game}:index`, entry.index);
50	}
51	
52	async function loadQuestion(game, qid) {
53	  const m = await getManifest();
54	  const url = m.games[game].index.replace(/index\.json$/, `${qid}.json`);
55	  return cached(m.version, `${game}:${qid}`, url);
56	}
