58	function utcToday() { return new Date().toISOString().slice(0, 10); }
59	function hashStr(s) { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; }
60	function pickRandom(index) { return String(index.items[Math.floor(Math.random() * index.items.length)][0]); }
61	function pickWeighted(index) {
62	  const total = index.items.reduce((s, it) => s + (Number(it[1]) || 1), 0);
63	  let r = Math.random() * total;
64	  for (const it of index.items) { r -= Number(it[1]) || 1; if (r <= 0) return String(it[0]); }
65	  return String(index.items[index.items.length - 1][0]);
66	}
67	function pickDaily(index, today = utcToday()) {
68	  const hit = index.items.find((it) => it[1] === today);
69	  if (hit) return String(hit[0]);
70	  const sorted = [...index.items].sort((a, b) => String(a[0]).localeCompare(String(b[0])));
71	  return String(sorted[hashStr(today) % sorted.length][0]);
72	}
73	const PICKERS = { "career-path": pickWeighted, contexto: pickDaily, imposter: (i) => String(i.items[0][0]) };
