75	/** One question for a game id (a room deals once so every member plays the same one). */
76	async function deal(gameId) {
77	  const index = await loadIndex(gameId);
78	  if (!index.items.length) throw new Error(`no questions for ${gameId}`);
79	  const qid = (PICKERS[gameId] || pickRandom)(index);
80	  return loadQuestion(gameId, qid);
81	}
